algorithm AgeCategory
    define age as integer;
    read age;
    if age < 13 then
        write 1;
    else
        if age < 18 then
            write 2;
        else
            if age < 65 then
                write 3;
            else
                write 4;
            endIf
        endIf
    endIf
endAlgorithm
